6	import { IChatQuotaService } from '../../../platform/chat/common/chatQuotaService';
7	import { Disposable } from '../../../util/vs/base/common/lifecycle';
8	import { IExtensionContribution } from '../../common/contributions';
9	
10	export class ChatQuotaContribution extends Disposable implements IExtensionContribution {
11		public readonly id = 'chat.quota';
12	
13		constructor(@IChatQuotaService chatQuotaService: IChatQuotaService) {
14			super();
15			this._register(commands.registerCommand('chat.enableAdditionalUsage', () => {
16				// Clear quota before opening the page to ensure that if the user enabled additional usage,
17				// the next request they send won't try to downgrade them to the base model.
18				chatQuotaService.clearQuota();
19				env.openExternal(Uri.parse('https://aka.ms/github-copilot-manage-overage'));
20			}));
21		}
22	}
