39	/**
40	 * Manages a single chat input notification for quota and rate limit status.
41	 *
42	 * Listens to `IChatQuotaService.onDidChange` and determines whether a
43	 * new threshold has been crossed, then shows the highest-priority notification:
44	 *
45	 * 1. **Quota exhausted** — info, not auto-dismissed, only dismissible via X.
46	 * 2. **Quota approaching** — info, auto-dismissed on next message.
47	 * 3. **Rate-limit warning** — info, auto-dismissed on next message.
48	 */
49	export class ChatInputNotificationContribution extends Disposable {
50	
51		private _notification: vscode.ChatInputNotification | undefined;
52		/** Tracks whether the current notification is the quota-exhausted variant. */
53		private _showingExhausted = false;
54		/** Whether a copilot token was present on the last {@link _update} call. */
55		private _hadCopilotToken = false;
56	
57		private readonly _quotaTracker: IThresholdTracker = { shown: new Set<number>(), baselineEstablished: false };
58		private readonly _sessionTracker: IThresholdTracker = { shown: new Set<number>(), baselineEstablished: false };
59		private readonly _weeklyTracker: IThresholdTracker = { shown: new Set<number>(), baselineEstablished: false };
60	
61		constructor(
62			@IAuthenticationService private readonly _authService: IAuthenticationService,
63			@IChatQuotaService private readonly _chatQuotaService: IChatQuotaService,
64		) {
65			super();
66			this._register(this._authService.onDidAuthenticationChange(() => { void this._update(); }));
67			this._register(this._chatQuotaService.onDidChange(() => { void this._update(); }));
68		}
69	
70		/**
71		 * Single entry point that determines the highest-priority notification
72		 * to show (or whether to hide).
73		 */
74		private async _update(): Promise<void> {
75			const hasCopilotToken = !!this._authService.copilotToken;
76			const wasSignedIn = this._hadCopilotToken;
77			this._hadCopilotToken = hasCopilotToken;
78	
79			// Detect signed-in → signed-out transition: clear the baseline/thresholds
80			// so the next sign-in re-establishes a fresh baseline, and hide.
81			if (wasSignedIn && !hasCopilotToken) {
82				this._resetThresholdTrackers();
83				this._hideNotification();
84				this._showingExhausted = false;
85				return;
86			}
87	
88			// Skip quota notifications for PRU users — only show for UBB.
89			const isQuotaNotificationEligible = !hasCopilotToken
90				|| !!this._authService.copilotToken?.isUsageBasedBilling;
91	
92			// Priority 1: Quota exhausted — sticky info notification
93			if (isQuotaNotificationEligible && this._chatQuotaService.quotaExhausted) {
94				this._showExhaustedNotification();
95				return;
96			}
97	
98			// Priority 2: Quota approaching threshold
99			if (isQuotaNotificationEligible) {
100				const quotaWarning = this._computeQuotaWarning();
101				if (quotaWarning) {
102					// Refresh quota from the server before surfacing the notification so
103					// the message reflects the latest usage. Display happens only after
104					// the refresh promise resolves.
105					await this._chatQuotaService.refreshQuota();
106					this._showQuotaApproachingWarning(quotaWarning);
107					return;
108				}
109			}
110	
111			// Priority 3: Rate-limit warning (session > weekly)
112			const rateLimitWarning = this._computeRateLimitWarning();
113			if (rateLimitWarning) {
114				await this._chatQuotaService.refreshQuota();
115				this._showRateLimitWarning(rateLimitWarning);
116				return;
117			}
118	
119			// Nothing new to show — only hide if the exhausted notification is
120			// active and the quota is no longer exhausted (state-driven).
121			if (this._showingExhausted && !this._chatQuotaService.quotaExhausted) {
122				this._hideNotification();
123			}
124		}
