126		/** Clears all baseline/threshold state (e.g. on sign-out). */
127		private _resetThresholdTrackers(): void {
128			for (const tracker of [this._quotaTracker, this._sessionTracker, this._weeklyTracker]) {
129				tracker.shown.clear();
130				tracker.baselineEstablished = false;
131			}
132		}
